#include <cstdint>
#include <iostream>
char* EncodeVarint64(char* dst, uint64_t v) {
    while (v >= 0x80) {
        *dst++ = static_cast<char>(v | 0x80);
        v >>= 7;
    }
    *dst++ = static_cast<char>(v);
    return dst;
}
int main(){
    char buf[10];
    char* p = EncodeVarint64(buf, 300);
    std::cout << (int)(p-buf) << " bytes" << std::endl;
    return 0;
}

